def icon_svg(code: str, *, fg: str, bg: str, x: float, y: float, size: float) -> str:
    """A disc of ``bg`` with the icon stroked in ``fg``, ``size`` mm wide, at (x, y)."""
    _, paths = ICONS[code]
    return (f'<g transform="translate({x:.3f} {y:.3f}) scale({size / 48:.5f})">'
            f'<circle cx="24" cy="24" r="24" fill="{bg}"/>'
            f'<g transform="translate(12 12)" fill="none" stroke="{fg}" stroke-width="2" '
            f'stroke-linecap="round" stroke-linejoin="round">{paths}</g></g>')
